arguments.file_text:
.page {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

.top-bar {
    background-color: #1a237e;
    color: white;
    padding: 0 1.5rem;
}

.navbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 1200px;
    margin: 0 auto;
    height: 60px;
}

.brand {
    color: white;
    font-size: 1.25rem;
    font-weight: bold;
    text-decoration: none;
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 1.5rem;
    margin: 0;
    padding: 0;
}

.nav-links a {
    color: rgba(255, 255, 255, 0.9);
    text-decoration: none;
    font-weight: 500;
}

.nav-links a:hover {
    color: white;
    text-decoration: underline;
}

.content-area {
    flex: 1;
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem 1.5rem;
    width: 100%;
    box-sizing: border-box;
}

.site-footer {
    background-color: #f5f5f5;
    border-top: 1px solid #e0e0e0;
    text-align: center;
    padding: 1rem;
    color: #666;
    font-size: 0.875rem;
}

@page "/"
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<section class="hero">
    <h1>Welcome to the University Course Catalog</h1>
    <p>Explore our departments and courses for the upcoming semester.</p>
    <a href="/courses" class="btn-primary">Browse All Courses</a>
</section>

<section class="departments-section">
    <h2>Departments</h2>
    <div class="dept-grid">
        @foreach (var dept in departments)
        {
            <a href="/courses?departmentId=@dept.Id" class="dept-card">
                <h3>@dept.Name</h3>
                <span class="dept-abbr">@dept.Abbreviation</span>
            </a>
        }
    </div>
</section>

<section class="featured-section">
    <h2>Featured Courses</h2>
    <div class="course-grid">
        @foreach (var course in featuredCourses)
        {
            <div class="course-card">
                <span class="course-code">@course.CourseCode</span>
                <h3>@course.Title</h3>
                <p>@course.Credits credits · @course.DepartmentName</p>
                <a href="/courses/@course.Id">View Details →</a>
            </div>
        }
    </div>
</section>

@code {
    private List<Department> departments = new();
    private List<Course> featuredCourses = new();

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        featuredCourses = Catalog.GetFeaturedCourses();
    }
}

.hero {
    text-align: center;
    padding: 3rem 1rem;
    background: linear-gradient(135deg, #e8eaf6, #c5cae9);
    border-radius: 8px;
    margin-bottom: 2.5rem;
}

.hero h1 {
    margin: 0 0 0.5rem;
    color: #1a237e;
}

.hero p {
    color: #555;
    font-size: 1.1rem;
    margin-bottom: 1.5rem;
}

.btn-primary {
    display: inline-block;
    background-color: #1a237e;
    color: white;
    padding: 0.75rem 1.5rem;
    border-radius: 4px;
    text-decoration: none;
    font-weight: 500;
}

.btn-primary:hover {
    background-color: #283593;
}

.departments-section, .featured-section {
    margin-bottom: 2.5rem;
}

.departments-section h2, .featured-section h2 {
    margin-bottom: 1rem;
    color: #333;
}

.dept-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 1rem;
}

.dept-card {
    display: block;
    padding: 1.25rem;
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s;
}

.dept-card:hover {
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

.dept-card h3 {
    margin: 0 0 0.25rem;
    font-size: 1rem;
}

.dept-abbr {
    font-size: 0.85rem;
    color: #666;
}

.course-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 1rem;
}

.course-card {
    padding: 1.25rem;
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
}

.course-card .course-code {
    font-size: 0.8rem;
    color: #1a237e;
    font-weight: 600;
    text-transform: uppercase;
}

.course-card h3 {
    margin: 0.25rem 0 0.5rem;
    font-size: 1.1rem;
}

.course-card p {
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 0.75rem;
}

.course-card a {
    color: #1a237e;
    text-decoration: none;
    font-weight: 500;
}

.course-card a:hover {
    text-decoration: underline;
}

.page {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

.top-bar {
    background-color: #1a237e;
