    background-color: #1a237e;
    color: white;
    padding: 0.75rem 1.5rem;
    border-radius: 4px;
    text-decoration: none;
    font-weight: 500;
}

.btn-primary:hover {
    background-color: #283593;
}

.departments-section, .featured-section {
    margin-bottom: 2.5rem;
}

.departments-section h2, .featured-section h2 {
    margin-bottom: 1rem;
    color: #333;
}

.dept-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 1rem;
}

.dept-card {
    display: block;
    padding: 1.25rem;
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s;
}

.dept-card:hover {
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

.dept-card h3 {
    margin: 0 0 0.25rem;
    font-size: 1rem;
}

.dept-abbr {
    font-size: 0.85rem;
    color: #666;
}

.course-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 1rem;
}

.course-card {
    padding: 1.25rem;
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
}

.course-card .course-code {
    font-size: 0.8rem;
    color: #1a237e;
    font-weight: 600;
    text-transform: uppercase;
}

.course-card h3 {
    margin: 0.25rem 0 0.5rem;
    font-size: 1.1rem;
}

.course-card p {
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 0.75rem;
}

.course-card a {
    color: #1a237e;
    text-decoration: none;
    font-weight: 500;
}

.course-card a:hover {
    text-decoration: underline;
}

