arguments.new_str:
@page "/"
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<section class="hero">
    <h1>Welcome to the University Course Catalog</h1>
    <p>Explore our departments and courses for the upcoming semester.</p>
    <a href="/courses" class="btn-primary">Browse All Courses</a>
</section>

<section class="departments-section">
    <h2>Departments</h2>
    <div class="dept-grid">
        @foreach (var dept in departments)
        {
            <a href="/courses?departmentId=@dept.Id" class="dept-card">
                <h3>@dept.Name</h3>
                <span class="dept-abbr">@dept.Abbreviation</span>
            </a>
        }
    </div>
</section>

<section class="featured-section">
    <h2>Featured Courses</h2>
    <div class="course-grid">
        @foreach (var course in featuredCourses)
        {
            <div class="course-card">
                <span class="course-code">@course.CourseCode</span>
                <h3>@course.Title</h3>
                <p>@course.Credits credits · @course.DepartmentName</p>
                <a href="/courses/@course.Id">View Details →</a>
            </div>
        }
    </div>
</section>

@code {
    private List<Department> departments = new();
    private List<Course> featuredCourses = new();

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        featuredCourses = Catalog.GetFeaturedCourses();
    }
}

.page {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

.top-bar {
    background-color: #1a237e;
    color: white;
    padding: 0 1.5rem;
}

.navbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 1200px;
    margin: 0 auto;
    height: 60px;
}

.brand {
    color: white;
    font-size: 1.25rem;
    font-weight: bold;
    text-decoration: none;
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 1.5rem;
    margin: 0;
    padding: 0;
}

.nav-links a {
    color: rgba(255, 255, 255, 0.9);
    text-decoration: none;
    font-weight: 500;
}

.nav-links a:hover {
    color: white;
    text-decoration: underline;
}

.content-area {
    flex: 1;
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem 1.5rem;
    width: 100%;
    box-sizing: border-box;
}

.site-footer {
    background-color: #f5f5f5;
    border-top: 1px solid #e0e0e0;
    text-align: center;
    padding: 1rem;
    color: #666;
    font-size: 0.875rem;
}

#blazor-error-ui {
    color-scheme: light only;
    background: lightyellow;
    bottom: 0;
    box-shadow: 0 -1px 2px rgba(0, 0, 0, 0.2);
    box-sizing: border-box;
    display: none;
    left: 0;
    padding: 0.6rem 1.25rem 0.7rem 1.25rem;
    position: fixed;
    width: 100%;
    z-index: 1000;
}

    #blazor-error-ui .dismiss {
        cursor: pointer;
        position: absolute;
        right: 0.75rem;
        top: 0.5rem;
    }

