    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

.top-bar {
    background-color: #1a237e;
    color: white;
    padding: 0 1.5rem;
}

.navbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 1200px;
    margin: 0 auto;
    height: 60px;
}

.brand {
    color: white;
    font-size: 1.25rem;
    font-weight: bold;
    text-decoration: none;
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 1.5rem;
    margin: 0;
    padding: 0;
}

.nav-links a {
    color: rgba(255, 255, 255, 0.9);
    text-decoration: none;
    font-weight: 500;
}

.nav-links a:hover {
    color: white;
    text-decoration: underline;
}

.content-area {
    flex: 1;
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem 1.5rem;
    width: 100%;
    box-sizing: border-box;
}

.site-footer {
    background-color: #f5f5f5;
    border-top: 1px solid #e0e0e0;
    text-align: center;
    padding: 1rem;
    color: #666;
    font-size: 0.875rem;
}

#blazor-error-ui {
    color-scheme: light only;
