@page "/enroll"
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Request Enrollment</h1>
<p class="page-desc">Fill out the form below to submit an enrollment request. You will receive a confirmation from the registrar's office.</p>

@if (submitted)
{
    <div class="success-message">
        <h2>✓ Request Submitted</h2>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@selectedCourseName</strong> has been received.</p>
        <p>The registrar's office will review your request and respond within 2-3 business days.</p>
        <a href="/courses">← Browse more courses</a>
    </div>
}
else
{
    <form method="post" @formname="enrollment" class="enrollment-form">
        <AntiforgeryToken />

        <div class="form-group">
            <label for="studentName">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" required />
            @if (errors.ContainsKey(nameof(Model.StudentName)))
            {
                <span class="field-error">@errors[nameof(Model.StudentName)]</span>
            }
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" placeholder="e.g., STU12345" required />
            @if (errors.ContainsKey(nameof(Model.StudentId)))
            {
                <span class="field-error">@errors[nameof(Model.StudentId)]</span>
            }
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <select id="courseId" name="Model.CourseId" required>
                <option value="0">-- Select a course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.CourseCode - @course.Title</option>
                }
            </select>
            @if (errors.ContainsKey(nameof(Model.CourseId)))
            {
                <span class="field-error">@errors[nameof(Model.CourseId)]</span>
            }
        </div>

        <button type="submit" class="btn-submit">Submit Enrollment Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<Course> courses = new();
    private Dictionary<string, string> errors = new();
    private bool submitted;
    private string selectedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpContext?.Request.Method == "POST")
        {
            HandleSubmit();
        }
    }

    [CascadingParameter]
    public HttpContext? HttpContext { get; set; }

    private void HandleSubmit()
    {
        errors.Clear();
        var validationResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var context = new System.ComponentModel.DataAnnotations.ValidationContext(Model);

        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(Model, context, validationResults, true))
        {
            foreach (var result in validationResults)
            {
                foreach (var member in result.MemberNames)
                {
                    if (!errors.ContainsKey(member))
                        errors[member] = result.ErrorMessage ?? "Invalid value.";
                }
            }
            return;
        }

        var course = Catalog.GetCourse(Model.CourseId);
        selectedCourseName = course?.Title ?? "Unknown Course";
        submitted = true;
    }
}

.page-desc {
    color: #555;
    margin-bottom: 2rem;
}

