.breadcrumb {
    margin-bottom: 1.5rem;
    font-size: 0.9rem;
    color: #666;
}

.breadcrumb a {
    color: #1a237e;
    text-decoration: none;
}

.breadcrumb a:hover {
    text-decoration: underline;
}

.detail-header {
    margin-bottom: 2rem;
}

.detail-header .course-code {
    font-size: 0.85rem;
    color: #1a237e;
    font-weight: 600;
    text-transform: uppercase;
}

.detail-header h1 {
    margin: 0.25rem 0 0.5rem;
}

.dept-label {
    color: #666;
    font-size: 1rem;
}

.detail-grid {
    display: grid;
    grid-template-columns: 1fr 300px;
    gap: 2rem;
}

@media (max-width: 768px) {
    .detail-grid {
        grid-template-columns: 1fr;
    }
}

.detail-main h2 {
    font-size: 1.2rem;
    margin: 1.5rem 0 0.75rem;
    color: #333;
}

.detail-main h2:first-child {
    margin-top: 0;
}

.instructor-card {
    background: #f9f9f9;
    padding: 1.25rem;
    border-radius: 6px;
    border-left: 3px solid #1a237e;
}

.instructor-card h3 {
    margin: 0 0 0.5rem;
    font-size: 1rem;
}

.instructor-card p {
    color: #555;
    font-size: 0.9rem;
    line-height: 1.5;
}

.info-box {
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.5rem;
}

.info-box h3 {
    margin: 0 0 1rem;
    font-size: 1.1rem;
}

.info-box dl {
    margin: 0 0 1.5rem;
}

.info-box dt {
    font-weight: 600;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.75rem;
}

.info-box dd {
    margin: 0.25rem 0 0;
    font-size: 0.95rem;
}

.btn-enroll {
    display: block;
    text-align: center;
    background-color: #1a237e;
    color: white;
    padding: 0.75rem;
    border-radius: 4px;
    text-decoration: none;
    font-weight: 500;
}

.btn-enroll:hover {
    background-color: #283593;
}

