.page-desc {
    color: #555;
    margin-bottom: 2rem;
}

.enrollment-form {
    max-width: 500px;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.35rem;
    font-size: 0.95rem;
}

.form-group input,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group select:focus {
    outline: none;
    border-color: #1a237e;
    box-shadow: 0 0 0 2px rgba(26, 35, 126, 0.1);
}

.field-error {
    display: block;
    color: #c62828;
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

.btn-submit {
    background-color: #1a237e;
    color: white;
    padding: 0.75rem 1.5rem;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    font-weight: 500;
}

.btn-submit:hover {
    background-color: #283593;
}

.success-message {
    background-color: #e8f5e9;
    border: 1px solid #a5d6a7;
    border-radius: 6px;
    padding: 2rem;
    max-width: 500px;
}

.success-message h2 {
    color: #2e7d32;
    margin: 0 0 0.75rem;
}

.success-message p {
    margin-bottom: 0.75rem;
    color: #333;
}

.success-message a {
    color: #1a237e;
    text-decoration: none;
}

.success-message a:hover {
    text-decoration: underline;
}

